<?php declare(strict_types=1);use App\Helpers\View;$e=static fn($v)=>View::e((string)$v);$total=array_sum(array_map(fn($x)=>(float)$x['total_amount'],$request['items']));$paid=array_sum(array_map(fn($x)=>(float)$x['amount'],$request['payments']));ob_start();?>
<div class="btp-shell"><header class="btp-banner"><div><small><?=$e($request['status'])?></small><h1><?=$e($request['reference']?:'FEB #'.$request['id'])?></h1><p><?=$e($request['chantier_code'].' · '.$request['chantier_name'])?> — <?=$e($request['beneficiary_name'])?></p></div><nav><a href="<?=$e(View::url('feb'))?>">Retour à la liste</a></nav></header>
<section class="btp-stats"><article><span>Demandé</span><strong><?=number_format($total,0,',',' ')?> F</strong></article><article><span>Payé</span><strong><?=number_format($paid,0,',',' ')?> F</strong></article><article><span>Reliquat</span><strong><?=number_format($total-$paid,0,',',' ')?> F</strong></article><article><span>Étape</span><strong><?=$e($request['step_label']??'Terminée')?></strong></article></section>
<section class="btp-panel"><h2>Besoins</h2><div class="btp-table-wrap"><table><thead><tr><th>Déboursé</th><th>Besoin</th><th>Qté</th><th>Total</th></tr></thead><tbody><?php foreach($request['items'] as $i):?><tr><td><?=$e($i['budget_description'])?></td><td><?=$e($i['description'])?></td><td><?=$e($i['quantity'].' '.$i['unit'])?></td><td><?=number_format((float)$i['total_amount'],0,',',' ')?> F</td></tr><?php endforeach;?></tbody></table></div><p><b>Motif :</b> <?=$e($request['purpose'])?></p></section>
<section class="btp-panel"><h2>Pièces justificatives</h2><?php foreach($request['documents'] as $doc):?><p><a href="<?=$e(View::url('feb/'.$request['id'].'/documents/'.$doc['id']))?>"><?=$e($doc['original_name'])?></a> · <?=$e($doc['category'])?></p><?php endforeach;?><?php if(!$request['documents']):?><p>Aucune pièce disponible.</p><?php endif;?></section>
<?php if($isOwner&&in_array($request['status'],['brouillon','complement'],true)):?><section class="btp-panel"><h2><?=$request['status']==='complement'?'Compléter et renvoyer':'Soumettre la demande'?></h2><form method="post" enctype="multipart/form-data" action="<?=$e(View::url('feb/'.$request['id'].'/documents'))?>"><input type="hidden" name="_csrf_token" value="<?=$e($csrf)?>"><input type="file" name="attachment" required><button>Ajouter une pièce</button></form><form method="post" action="<?=$e(View::url('feb/'.$request['id'].'/soumettre'))?>"><input type="hidden" name="_csrf_token" value="<?=$e($csrf)?>"><button class="btp-primary">Soumettre</button></form></section><?php endif;?>
<?php if($isOwner&&in_array($request['status'],['brouillon','soumis','complement'],true)):?><section class="btp-panel"><form method="post" action="<?=$e(View::url('feb/'.$request['id'].'/annuler'))?>" onsubmit="return confirm('Annuler cette FEB ?')"><input type="hidden" name="_csrf_token" value="<?=$e($csrf)?>"><button>Annuler la FEB</button></form></section><?php endif;?>
<?php if($canDecide&&$request['status']==='soumis'):?><section class="btp-panel"><h2>Décision</h2><form method="post" action="<?=$e(View::url('feb/'.$request['id'].'/decision'))?>"><input type="hidden" name="_csrf_token" value="<?=$e($csrf)?>"><select name="decision"><option value="approuve">Approuver</option><option value="complement">Demander un complément</option><option value="refuse">Refuser</option></select><textarea name="comment" placeholder="Commentaire"></textarea><button class="btp-primary">Enregistrer</button></form></section><?php endif;?>
<?php if($canPay&&in_array($request['status'],['approuve','partiellement_paye'],true)):?><section class="btp-panel"><h2>Enregistrer un paiement</h2><form method="post" action="<?=$e(View::url('feb/'.$request['id'].'/paiements'))?>"><input type="hidden" name="_csrf_token" value="<?=$e($csrf)?>"><div class="btp-form-grid"><label>Référence<input name="payment_reference" required></label><label>Montant<input type="number" name="amount" min="0.01" step="0.01" max="<?=$total-$paid?>" required></label><label>Moyen<input name="method" required></label><label>Date<input type="datetime-local" name="paid_at" required></label></div><textarea name="notes" placeholder="Note"></textarea><button class="btp-primary">Confirmer le paiement</button></form></section><?php endif;?>
<section class="btp-panel"><h2>Historique vérifiable</h2><?php foreach($request['history'] as $h):?><p><b><?=$e($h['created_at'])?> · <?=$e($h['event_type'])?></b> — <?=$e($h['actor_name']??'Système')?> (<?=$e(($h['from_status']??'—').' → '.($h['to_status']??'—'))?>)</p><?php endforeach;?></section></div>
<?php $content=ob_get_clean();require BASE_PATH.'/views/layouts/module.php';
